                     type: 'text',
                     name: 'fullName',
                     required: true,
                     autocomplete: 'name',
                     placeholder: 'Jane Doe',
                     helpText: 'Use the name you want us to address you by.'
                   })}

                   ${FormField({
                     id: 'email-address',
                     label: 'Email address',
                     type: 'email',
                     name: 'email',
                     required: true,
                     autocomplete: 'email',
                     placeholder: 'jane@company.com',
                     helpText: 'We will use this to reply to your request.'
                   })}

                   ${FormField({
                     id: 'phone-number',
                     label: 'Phone number',
                     type: 'tel',
                     name: 'phone',
                     required: false,
                     autocomplete: 'tel',
                     placeholder: '(555) 555-5555',
                     helpText: 'Optional. Include a number like +1 555 555 5555 or (555) 555-5555.'
                   })}

                   <div class="actions">
                     <button type="submit">Submit request</button>
                   </div>
                 </form>
                 <p class="status" id="form-status" aria-live="polite"></p>
               </div>
             </section>
           </div>
         </main>
